package org.jfree.data.time;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class Week_equals_TriageGen0Test {

    @Test
    public void testEquals_SameInstance() {
        Week week = new Week(1, 2023);
        assertTrue(week.equals(week));
    }

    @Test
    public void testEquals_DifferentType() {
        Week week = new Week(1, 2023);
        assertFalse(week.equals("Not a Week object"));
        assertFalse(week.equals(null));
    }

    @Test
    public void testEquals_SameValues() {
        Week week1 = new Week(10, 2023);
        Week week2 = new Week(10, 2023);
        assertTrue(week1.equals(week2));
    }

    @Test
    public void testEquals_DifferentWeek() {
        Week week1 = new Week(10, 2023);
        Week week2 = new Week(11, 2023);
        assertFalse(week1.equals(week2));
    }

    @Test
    public void testEquals_DifferentYear() {
        Week week1 = new Week(10, 2023);
        Week week2 = new Week(10, 2024);
        assertFalse(week1.equals(week2));
    }

    @Test
    public void testEquals_AllDifferent() {
        Week week1 = new Week(10, 2023);
        Week week2 = new Week(11, 2024);
        assertFalse(week1.equals(week2));
    }
}
